    let ob = outboard(&backend, &data, BlockSize::ZERO);

    let pre = PreOrderOutboard {
        root: ob.root.clone(),
        tree: ob.tree,
        data: ob.data.clone(),
    };

    assert_eq!(Outboard::root(&pre), ob.root);
    assert_eq!(pre.tree(), ob.tree);

    let root_node = ob.tree.root();
    let pair = pre.load(root_node).unwrap();
    assert!(pair.is_some());
}

let mut current = decoder;
let mut leaf_data = Vec::new();
loop {
    match current.next().await {
        ResponseDecoderNext::More((dec, result)) => {
            let item = result.expect("decode should succeed");
            if let BaoContentItem::Leaf(leaf) = item {
                leaf_data.extend_from_slice(&leaf.data);
            }
            current = dec;
        }
        ResponseDecoderNext::Done(_) => break,
    }
}
assert_eq!(leaf_data, data);

